#!/usr/bin/env python3
"""Underline all headline paragraphs in the unpacked quarterly_report.docx.

Headlines are the all-caps title lines in the report (no Heading styles are
used in this document). A headline paragraph is detected as one whose text
contains at least one letter, every letter is uppercase, and whose trimmed
length is short (<= 80 chars). For each such paragraph, all of its runs get
<w:u w:val="single"/> added to their run properties.
"""
import sys
import defusedxml.minidom as minidom
from pathlib import Path

unpacked = sys.argv[1] if len(sys.argv) > 1 else "unpacked_report"
doc_path = Path(unpacked) / "word" / "document.xml"

dom = minidom.parse(str(doc_path))

def para_text(p):
    chunks = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            chunks.append(t.firstChild.data)
    return "".join(chunks)

def is_headline(text):
    stripped = text.strip()
    if not stripped:
        return False
    if not any(ch.isalpha() for ch in stripped):
        return False
    if any(ch.islower() for ch in stripped):
        return False
    if len(stripped) > 80:
        return False
    return True

headline_paras = []
for p in dom.getElementsByTagName("w:p"):
    if is_headline(para_text(p)):
        headline_paras.append(p)

runs_underlined = 0
for p in headline_paras:
    for r in p.getElementsByTagName("w:r"):
        # Only underline runs that carry visible text.
        has_text = any(
            (t.firstChild is not None and t.firstChild.data.strip())
            for t in r.getElementsByTagName("w:t")
        )
        if not has_text:
            continue
        rprs = r.getElementsByTagName("w:rPr")
        if rprs:
            rpr = rprs[0]
        else:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        us = rpr.getElementsByTagName("w:u")
        if us:
            us[0].setAttribute("w:val", "single")
        else:
            u = dom.createElement("w:u")
            u.setAttribute("w:val", "single")
            rpr.appendChild(u)
        runs_underlined += 1

with open(doc_path, "wb") as f:
    f.write(dom.toprettyxml(indent="  ", encoding="ascii"))

print(f"headline paragraphs found: {len(headline_paras)}")
print(f"runs underlined: {runs_underlined}")
for p in headline_paras:
    print("headline:", para_text(p).strip())

